/* @lc app=leetcode id=3686 lang=kotlin */ class Solution { fun countStableSubsequences(nums: IntArray): Int = 1_000_000_007L.let { M -> nums.fold(listOf(0L, 0L, 0L, 0L)) { d, x -> (x % 2).let { q -> d.toMutableList().also { nd -> nd.set(q * 2, (d[q * 2] + d[(1 - q) * 2] + d[(1 - q) * 2 + 1] + 1) % M) }.also { nd -> nd.set(q * 2 + 1, (d[q * 2 + 1] + d[q * 2]) % M) } } }.sum().let { (it % M).toInt() } } }